artifact.schema:
export interface InventoryProps {
  // Required
  readonly providers: ProviderInstance[];
  readonly steps:     StepDefinition[];

  // Optional
  readonly layout?:   LayoutConfig;
  readonly i18n?:     I18nConfig;
  readonly theme?:    ThemeConfig;

  // Observability
  readonly onReady?:  () => void;
  readonly onError?:  (err: InventoryError) => void;
  readonly onEvent?:  (event: TypedEvent) => void;

  // Customization (escape hatch — prefer extensions when possible)
  readonly overridePatterns?: Partial<Record<PatternId, ComponentType>>;
  readonly customStyle?:       CustomStyleMap;

  // Experimental (React 19+)
  readonly experimental?: {
    signals?:   boolean;     // use signals for high-freq providers
    streaming?: boolean;     // SSR streaming with use(promise)
    activity?:  boolean;     // preserve state across step changes via <Activity>
  };

  readonly children?: ReactNode;   // global slots (modals, toasts)
}

export function Inventory(props: InventoryProps): JSX.Element;

artifact.example:
// apps/panaderia/app/layout.tsx
import { Inventory } from '@surte/shell-runtime';
import { providers, steps } from '../inventory/config';

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="es-PE">
      <body>
        <Inventory
          providers={providers}
          steps={steps}
          layout={{ shell: 'sidebar-topbar', sidebar: { collapsible: true } }}
          experimental={{ signals: true, streaming: true }}
          onReady={() => console.log('Panadería lista')}
          onError={(err) => Sentry.captureException(err)}
        >
          {children}
        </Inventory>
      </body>
    </html>
  );
}
